import{_ as r,c as o,o as i,a5 as t}from"./chunks/framework.DuCYAsAJ.js";const d=JSON.parse('{"title":"User RPC 服务","description":"","frontmatter":{"title":"User RPC 服务","date":"2026-05-24T00:00:00.000Z","source":"https://app.devin.ai/org/feed/wiki/qiqi776/zfeed?branch=main#7","branch":"main","level":0,"order":7},"headers":[],"relativePath":"posts/projects/zfeed/07-user-rpc-service/index.md","filePath":"posts/projects/zfeed/07-user-rpc-service/index.md","lastUpdated":1779632679000}'),a={name:"posts/projects/zfeed/07-user-rpc-service/index.md"};function l(c,e,p,s,g,n){return i(),o("div",null,[...e[0]||(e[0]=[t('<h1 id="user-rpc-服务" tabindex="-1">User RPC 服务 <a class="header-anchor" href="#user-rpc-服务" aria-label="Permalink to &quot;User RPC 服务&quot;">​</a></h1><details><summary>相关源文件</summary><ul><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/front/doc/user/user.api" target="_blank" rel="noreferrer">app/front/doc/user/user.api</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/front/internal/logic/user/loginlogic.go" target="_blank" rel="noreferrer">app/front/internal/logic/user/loginlogic.go</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/front/internal/logic/user/loginlogic_test.go" target="_blank" rel="noreferrer">app/front/internal/logic/user/loginlogic_test.go</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/front/internal/logic/user/registerlogic.go" target="_blank" rel="noreferrer">app/front/internal/logic/user/registerlogic.go</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/front/internal/logic/user/registerlogic_test.go" target="_blank" rel="noreferrer">app/front/internal/logic/user/registerlogic_test.go</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/front/internal/middleware/sessionauth.go" target="_blank" rel="noreferrer">app/front/internal/middleware/sessionauth.go</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/user/internal/config/config.go" target="_blank" rel="noreferrer">app/rpc/user/internal/config/config.go</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/user/internal/logic/batchgetuserlogic.go" target="_blank" rel="noreferrer">app/rpc/user/internal/logic/batchgetuserlogic.go</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/user/internal/logic/getmelogic.go" target="_blank" rel="noreferrer">app/rpc/user/internal/logic/getmelogic.go</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/user/internal/logic/getuserlogic.go" target="_blank" rel="noreferrer">app/rpc/user/internal/logic/getuserlogic.go</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/user/internal/logic/getuserprofilelogic.go" target="_blank" rel="noreferrer">app/rpc/user/internal/logic/getuserprofilelogic.go</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/user/internal/logic/loginlogic.go" target="_blank" rel="noreferrer">app/rpc/user/internal/logic/loginlogic.go</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/user/internal/logic/mobile_test.go" target="_blank" rel="noreferrer">app/rpc/user/internal/logic/mobile_test.go</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/user/internal/logic/registerlogic.go" target="_blank" rel="noreferrer">app/rpc/user/internal/logic/registerlogic.go</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/user/internal/logic/registerlogic_defaults_test.go" target="_blank" rel="noreferrer">app/rpc/user/internal/logic/registerlogic_defaults_test.go</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/user/internal/repositories/user_repository.go" target="_blank" rel="noreferrer">app/rpc/user/internal/repositories/user_repository.go</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/user/internal/svc/servicecontext.go" target="_blank" rel="noreferrer">app/rpc/user/internal/svc/servicecontext.go</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/user/user.go" target="_blank" rel="noreferrer">app/rpc/user/user.go</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/orm/orm.go" target="_blank" rel="noreferrer">orm/orm.go</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/pkg/mobilex/mobile.go" target="_blank" rel="noreferrer">pkg/mobilex/mobile.go</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/pkg/mobilex/mobile_test.go" target="_blank" rel="noreferrer">pkg/mobilex/mobile_test.go</a></li></ul></details><p><code>user-rpc</code> 服务是 zfeed 生态中用户身份和资料管理的中心权威。它处理注册、基于密码的认证、会话签发和细粒度资料管理等敏感操作。它是 <code>zfeed_user</code> 表的事实来源，并为 <code>content-rpc</code> 等其他服务提供批量查询能力，用于补全用户元数据。</p><h2 id="服务架构" tabindex="-1">服务架构 <a class="header-anchor" href="#服务架构" aria-label="Permalink to &quot;服务架构&quot;">​</a></h2><p>该服务遵循清晰的架构模式，将 gRPC 传输层、业务逻辑和数据持久化分离。</p><h3 id="数据流-注册与登录" tabindex="-1">数据流：注册与登录 <a class="header-anchor" href="#数据流-注册与登录" aria-label="Permalink to &quot;数据流：注册与登录&quot;">​</a></h3><p>用户注册或登录时，服务会执行校验，调用 <code>UserRepository</code> 进行持久化，并通过共享工具在 Redis 中管理会话状态。</p><p>标题：用户认证与注册流程</p><p>来源：<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/user/internal/logic/registerlogic.go#L38-L102" target="_blank" rel="noreferrer">app/rpc/user/internal/logic/registerlogic.go#38-102</a> <a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/user/internal/logic/loginlogic.go#L34-L72" target="_blank" rel="noreferrer">app/rpc/user/internal/logic/loginlogic.go#34-72</a> <a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/user/internal/repositories/user_repository.go#L95-L117" target="_blank" rel="noreferrer">app/rpc/user/internal/repositories/user_repository.go#95-117</a></p><h2 id="核心组件" tabindex="-1">核心组件 <a class="header-anchor" href="#核心组件" aria-label="Permalink to &quot;核心组件&quot;">​</a></h2><h3 id="_1-手机号校验与归一化" tabindex="-1">1. 手机号校验与归一化 <a class="header-anchor" href="#_1-手机号校验与归一化" aria-label="Permalink to &quot;1. 手机号校验与归一化&quot;">​</a></h3><p>服务使用 <code>mobilex</code> 包保证手机号处理一致，支持标准 11 位中国大陆号码、<code>86</code> 前缀和 E.164 格式。</p><ul><li>归一化：将多种格式（例如 <code>+86138...</code>）转换为标准 11 位字符串，用于数据库索引。<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/pkg/mobilex/mobile.go#L5-L15" target="_blank" rel="noreferrer">pkg/mobilex/mobile.go#5-15</a></li><li>候选查找：按手机号搜索用户时，仓储会生成多个候选值（原始值、带 86、带 +86），确保历史格式或不同输入格式仍能找到正确记录。<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/pkg/mobilex/mobile.go#L22-L41" target="_blank" rel="noreferrer">pkg/mobilex/mobile.go#22-41</a></li></ul><h3 id="_2-用户仓储-userrepository" tabindex="-1">2. 用户仓储（<code>UserRepository</code>） <a class="header-anchor" href="#_2-用户仓储-userrepository" aria-label="Permalink to &quot;2. 用户仓储（`UserRepository`）&quot;">​</a></h3><p>仓储使用 GORM 抽象所有与 <code>zfeed_user</code> 表的交互。它负责在数据库 <code>model.ZfeedUser</code> 和业务层 <code>do.UserDO</code> 之间映射。</p><table tabindex="0"><thead><tr><th>方法</th><th>说明</th><th>实现细节</th></tr></thead><tbody><tr><td><code>GetByMobile</code></td><td>按手机号查找活跃用户。</td><td>遍历 <code>mobilex.LookupCandidates</code> 生成的候选值。<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/user/internal/repositories/user_repository.go#L37-L53" target="_blank" rel="noreferrer">app/rpc/user/internal/repositories/user_repository.go#37-53</a></td></tr><tr><td><code>GetByID</code></td><td>获取单个用户资料。</td><td>按 <code>id</code> 和 <code>is_deleted = 0</code> 过滤。<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/user/internal/repositories/user_repository.go#L55-L72" target="_blank" rel="noreferrer">app/rpc/user/internal/repositories/user_repository.go#55-72</a></td></tr><tr><td><code>BatchGetByIDs</code></td><td>高效获取多个用户资料。</td><td>使用 <code>WHERE id IN ?</code>，为 Feed 补全提供高性能读取。<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/user/internal/repositories/user_repository.go#L74-L93" target="_blank" rel="noreferrer">app/rpc/user/internal/repositories/user_repository.go#74-93</a></td></tr><tr><td><code>UpdateProfile</code></td><td>局部更新用户字段。</td><td>使用 <code>UserProfilePatch</code> 和 GORM <code>Updates(map[string]any)</code> 执行字段级更新。<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/user/internal/repositories/user_repository.go#L119-L169" target="_blank" rel="noreferrer">app/rpc/user/internal/repositories/user_repository.go#119-169</a></td></tr></tbody></table><p>来源：<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/user/internal/repositories/user_repository.go#L15-L21" target="_blank" rel="noreferrer">app/rpc/user/internal/repositories/user_repository.go#15-21</a></p><h3 id="_3-会话管理" tabindex="-1">3. 会话管理 <a class="header-anchor" href="#_3-会话管理" aria-label="Permalink to &quot;3. 会话管理&quot;">​</a></h3><p>会话不存储在 MySQL 中，而是由 Redis 管理，以支持 <code>front-api</code> 中间件中的高并发校验。</p><ul><li>Token 生成：使用加密安全随机 token。<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/user/internal/logic/registerlogic.go#L92-L92" target="_blank" rel="noreferrer">app/rpc/user/internal/logic/registerlogic.go#92</a></li><li>TTL：会话时长可通过 <code>GetSessionTTL</code> 配置。<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/user/internal/logic/registerlogic.go#L91-L91" target="_blank" rel="noreferrer">app/rpc/user/internal/logic/registerlogic.go#91</a></li><li>存储：<code>SaveSession</code> 工具将 <code>token -&gt; userID</code> 映射持久化到 Redis。<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/user/internal/logic/registerlogic.go#L93-L93" target="_blank" rel="noreferrer">app/rpc/user/internal/logic/registerlogic.go#93</a></li></ul><h2 id="资料初始化逻辑" tabindex="-1">资料初始化逻辑 <a class="header-anchor" href="#资料初始化逻辑" aria-label="Permalink to &quot;资料初始化逻辑&quot;">​</a></h2><p>注册过程中，如果可选字段缺失，服务会应用默认值，确保每个用户都有完整资料。</p><ul><li>昵称：未提供时默认使用用户手机号。<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/user/internal/logic/registerlogic.go#L113-L119" target="_blank" rel="noreferrer">app/rpc/user/internal/logic/registerlogic.go#113-119</a></li><li>邮箱：如果留空，会生成内部占位邮箱，例如 <code>register-138...@zfeed.local</code>。<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/user/internal/logic/registerlogic.go#L121-L140" target="_blank" rel="noreferrer">app/rpc/user/internal/logic/registerlogic.go#121-140</a></li><li>生日：将时间戳截断到当天开始时间（00:00:00），以保证隐私和一致性。<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/user/internal/logic/registerlogic.go#L142-L152" target="_blank" rel="noreferrer">app/rpc/user/internal/logic/registerlogic.go#142-152</a></li></ul><h2 id="实现细节-logic-类" tabindex="-1">实现细节：Logic 类 <a class="header-anchor" href="#实现细节-logic-类" aria-label="Permalink to &quot;实现细节：Logic 类&quot;">​</a></h2><p>服务实现被拆分为多个专门的 logic 类，每个类处理一个特定 gRPC 方法。</p><p>标题：User RPC 逻辑映射</p><p>来源：<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/user/internal/logic/registerlogic.go#L22-L27" target="_blank" rel="noreferrer">app/rpc/user/internal/logic/registerlogic.go#22-27</a> <a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/user/internal/logic/loginlogic.go#L18-L23" target="_blank" rel="noreferrer">app/rpc/user/internal/logic/loginlogic.go#18-23</a> <a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/user/internal/logic/getmelogic.go#L14-L19" target="_blank" rel="noreferrer">app/rpc/user/internal/logic/getmelogic.go#14-19</a></p><h3 id="批量用户查询" tabindex="-1">批量用户查询 <a class="header-anchor" href="#批量用户查询" aria-label="Permalink to &quot;批量用户查询&quot;">​</a></h3><p><code>BatchGetUser</code> 逻辑由 <code>content-rpc</code> 和 <code>interaction-rpc</code> 使用，允许系统在一次往返中解析一组内容项所需的用户头像和昵称。这可以在 RPC 层避免 “N+1” 查询问题。</p><p>来源：<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/user/internal/repositories/user_repository.go#L74-L93" target="_blank" rel="noreferrer">app/rpc/user/internal/repositories/user_repository.go#74-93</a></p>',30)])])}const h=r(a,[["render",l]]);export{d as __pageData,h as default};
